/*Recovery partition depended on Boot header version to verify, check table:
  ----------------------------------------------------------------------
  Android             |          AN-R        |         AN-S
  ----------------------------------------------------------------------
  Boot header version |    V1    |   V2      |  V3        |      V4
  ----------------------------------------------------------------------
  nonAB               | recovery |  recovery | recovery   |  vendor_boot
  ----------------------------------------------------------------------
  AB                  |   boot   |   boot   | vendor_boot |  vendor_boot
  ----------------------------------------------------------------------

When boot to recovery mode, the recovery partition should be verified by AVB
for boot safety and reliability.

On Android devices not using A/B, the `recovery` partition usually isn't updated along
with other partitions and therefore can't be referenced from the main `vbmeta` partition.

So the LIBAVB provided a flag called 'AVB_SLOT_VERIFY_FLAGS_NO_VBMETA_PARTITION' to support it.
When AVB_SLOT_VERIFY_FLAGS_NO_VBMETA_PARTITION has been selected, AVB would not checked the vbmeta.
Instead, AVB would validated each partition in request_partition list.

And we used the flag: 'RECOVERY_VERIFY_FLAG' to use it:
if AVB_SLOT_VERIFY_FLAGS_NO_VBMETA_PARTITION is select by RECOVERY_VERIFY_FLAG,
AVB would not checked vbmeta, and verify each partition which contain in requested_partitions_recovery_mode[].
if AVB_SLOT_VERIFY_FLAGS_NONE is select by RECOVERY_VERIFY_FLAG,
AVB would checked vbmeta, and verify the partitions contain in vbmeta.

The recovery partition is exist or into vendor_boot are depended on Boot header version
And it is influenced the vbmeta should check or not, the case are show as below table:
  ----------------------------------------------------------------------
  Boot header version |    V1      |     V2      |  V3         |      V4
  ----------------------------------------------------------------------
  nonAB               |not checked | not checked | not checked |  checked
  ----------------------------------------------------------------------
  AB                  |  checked   |   checked   | checked     |  checked
  ----------------------------------------------------------------------
*/
#if !defined(CONFIG_ANDROID_AB)
#if defined(ANDROID_BOOT_HEADER_VERSION_V1) || defined(ANDROID_BOOT_HEADER_VERSION_V2) || defined(ANDROID_BOOT_HEADER_VERSION_V3)
static const char * const requested_partitions_recovery_mode[] = {"recovery",
					     NULL};
#define RECOVERY_VERIFY_FLAG AVB_SLOT_VERIFY_FLAGS_NO_VBMETA_PARTITION
#define RECOVERY_PARTNAME "recovery"

#elif defined(ANDROID_BOOT_HEADER_VERSION_V4)
static const char * const * requested_partitions_recovery_mode = requested_partitions;
#define RECOVERY_VERIFY_FLAG AVB_SLOT_VERIFY_FLAGS_NONE
#define RECOVERY_PARTNAME "vendor_boot"

#else
static const char * const * requested_partitions_recovery_mode = requested_partitions;
#define RECOVERY_VERIFY_FLAG AVB_SLOT_VERIFY_FLAGS_NONE
#define RECOVERY_PARTNAME "vendor_boot"
#endif

#else//defined(CONFIG_ANDROID_AB)
static const char * const * requested_partitions_recovery_mode = requested_partitions;
#define RECOVERY_VERIFY_FLAG AVB_SLOT_VERIFY_FLAGS_NONE

#if defined(ANDROID_BOOT_HEADER_VERSION_V1) || defined(ANDROID_BOOT_HEADER_VERSION_V2)
#define RECOVERY_PARTNAME "boot"
#elif defined(ANDROID_BOOT_HEADER_VERSION_V3) || defined(ANDROID_BOOT_HEADER_VERSION_V4)
#define RECOVERY_PARTNAME "vendor_boot"
#else
#define RECOVERY_PARTNAME "vendor_boot"
#endif
#endif

#endif

static void get_verified_parts(const char* const* requested_partitions, AvbPartitionData* part_data, size_t num_loaded_partitions , const char** verified_parts)
{
	int i,j;
	for(i=0; i < num_loaded_partitions; i++)
	{
		verified_parts[i] = NULL;
		for(j=0; requested_partitions[j] != NULL; j++)
		{
			if(!strncmp(part_data[i].partition_name, requested_partitions[j], strlen(part_data[i].partition_name)))
			{
				verified_parts[i] = part_data[i].partition_name;
			}
		}
	}
}

