// Choose unused index 10 for PMU version rollback index
#if (CONFIG_ROLLBACK_INDEX_IN_RPMB == 1)
#include <program_rpmb_rollback_index.h>
#define PMU_ROLLBACK_INDEX_LOCATION 10
#endif

#if (CONFIG_AB_SIDELOAD == 1)
#define DTB_VERSION_STRUCT_MAGIC "avb_version     "
#define DTB_VERSION_STRUCT_MAGIC_LEN 16
typedef struct
{
	u64 ta_avb_rollback_indexes[AVB_MAX_NUMBER_OF_ROLLBACK_INDEX_LOCATIONS];
	u64 pmu_rollback_indexes;
	char magic[DTB_VERSION_STRUCT_MAGIC_LEN]; //magic = "avb_version     "
} avb_version; //288 bytes

static avb_version version;

static int rollbackindexes_to_dtb(AvbSlotVerifyData* AvbData)
{
	int i;
	memset(&version, 0, sizeof(avb_version));
	avb_memcpy(version.magic, DTB_VERSION_STRUCT_MAGIC, DTB_VERSION_STRUCT_MAGIC_LEN);
	for(i=0; i<AVB_MAX_NUMBER_OF_ROLLBACK_INDEX_LOCATIONS; i++)
	{
		version.ta_avb_rollback_indexes[i] = AvbData->rollback_indexes[i];
	}
	version.pmu_rollback_indexes = get_pmu_rollback_index();
#if (CONFIG_ROLLBACK_INDEX_IN_RPMB == 1)
	version.ta_avb_rollback_indexes[PMU_ROLLBACK_INDEX_LOCATION] = version.pmu_rollback_indexes;
#endif
	UBOOT_DUMP(&version, sizeof(avb_version));
	setup_avb_data_for_dtb((char*)(&version), sizeof(avb_version));
	return 0;
}
#endif

static void remove_duplicate_args(void)
{
	run_command("deletebootargs androidboot.vbmeta.device", 0);
	run_command("deletebootargs androidboot.vbmeta.avb_version", 0);
	run_command("deletebootargs androidboot.vbmeta.device_state", 0);
	run_command("deletebootargs androidboot.vbmeta.hash_alg", 0);
	run_command("deletebootargs androidboot.vbmeta.size", 0);
	run_command("deletebootargs androidboot.vbmeta.digest", 0);
	run_command("deletebootargs androidboot.vbmeta.invalidate_on_error", 0);
	run_command("deletebootargs androidboot.veritymode", 0);
	run_command("deletebootargs androidboot.verifiedbootstate", 0);
}
